from odoo import api,fields,models,tools,_
from odoo.exceptions import ValidationError
from datetime import datetime,timedelta
from dateutil.relativedelta import relativedelta
import random,logging
_logger=logging.getLogger(__name__)
class OvertimeReport(models.Model):
	_name='hr.ph.pay.ot.report';_description='Overtime Report';_auto=False;_rec_name='id';company_id=fields.Many2one('res.company',string='Company');year_month=fields.Char();payroll_id=fields.Many2one('hr.ph.payroll','Payroll No.');employee_id=fields.Many2one('hr.employee',string='Employee');date_to=fields.Date(related='payroll_id.date_to');name=fields.Char();seq_name=fields.Char('Sequence Name');year=fields.Char();amount=fields.Float(digits=(0,2));time_hrs=fields.Float(digits=(0,4))
	def init(A):tools.drop_view_if_exists(A.env.cr,'hr_ph_pay_ot_report');A.env.cr.execute("\n            CREATE VIEW hr_ph_pay_ot_report AS (\n                SELECT MIN(pc.id) AS id,\n                    ps.company_id,\n                    pc.year_month,\n                    ps.payroll_id,\n                    pc.employee_id,\n                    pc.name,\n                    TO_CHAR(COALESCE(wt.seq, 99999), 'FM00000') || ' ' || pc.name AS seq_name,\n                    left(pc.year_month, 4) AS year,\n                    SUM(pc.amount) AS amount,\n                    SUM(\n                        CASE \n                            WHEN pc.unit='month' THEN pc.qty * 8.0 * (ps.emr_days/12.0)\n                            WHEN pc.unit='day' THEN pc.qty * 8.0\n                            WHEN pc.unit='hour' THEN pc.qty\n                            WHEN pc.unit='minute' THEN pc.qty/60.0\n                        ELSE\n                            0.0\n                        END\n                    ) AS time_hrs\n                FROM hr_ph_pay_computation AS pc\n                INNER JOIN hr_ph_payslip AS ps\n                    ON ps.id = pc.payslip_id\n                LEFT JOIN (\n                    SELECT wt0.seq, wt0.name\n                    FROM ez_work_type AS wt0\n                    INNER JOIN ez_work_type_group AS wtg\n                    ON wt0.work_type_group_id = wtg.id\n                    WHERE wtg.name = 'Default'\n                ) AS wt ON pc.name = wt.name\n                WHERE\n                    ps.state != 'draft'\n                GROUP BY \n                    ps.company_id, \n                    pc.year_month, \n                    ps.payroll_id, \n                    pc.employee_id, \n                    pc.name, \n                    seq_name \n            )")